import XCTest
@testable import CookiesEditor

final class ReferenceProjectTests:XCTestCase {
    // Created through the unmodified YTyper 4.5 UI on 2026-10-10. No account data.
    // APK SHA-256: a3758bcdf50c802c25d9023c90456f6bdde922a94cda08fc3ce737c2a9b29789.
    func testActualAndroidBlankProjectPreservesDimensionsAndSourceBytes()throws {
        let root=FileManager.default.temporaryDirectory.appendingPathComponent(UUID().uuidString)
        defer{try? FileManager.default.removeItem(at:root)}
        let original=root.appendingPathComponent("original"),output=root.appendingPathComponent("imported")
        for path in [original.appendingPathComponent("pages"),original.appendingPathComponent("assets"),output]{try FileManager.default.createDirectory(at:path,withIntermediateDirectories:true)}
        try Data(Self.metadata.utf8).write(to:original.appendingPathComponent("project_meta.json"))
        try Data(Self.page.utf8).write(to:original.appendingPathComponent("pages/e77dd769-1198-4dec-a9e0-798d04bb5cb1.json"))
        let image=try XCTUnwrap(Data(base64Encoded:Self.image,options:.ignoreUnknownCharacters))
        try image.write(to:original.appendingPathComponent("assets/bg_e77dd769-1198-4dec-a9e0-798d04bb5cb1.jpg"))
        let pages=try XCTUnwrap(ReferenceProjectImport.importFolder(original,root:output)),page=try XCTUnwrap(pages.first)
        XCTAssertEqual(pages.count,1);XCTAssertEqual(page.width,1080);XCTAssertEqual(page.height,1920);XCTAssertTrue(page.layers.isEmpty)
        let directory=output.appendingPathComponent(page.id.uuidString)
        XCTAssertEqual(try Data(contentsOf:directory.appendingPathComponent(page.source)),image,"Android's .jpg asset contains PNG bytes; preserve its true format and every byte")
        XCTAssertEqual(try Data(contentsOf:directory.appendingPathComponent(page.raw)).count,1080*1920*4)
        let exported=try ImagePipeline.exportPNG(page,directory:directory);XCTAssertEqual(try Data(contentsOf:exported),image)
    }
